begin;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,phone,phone_confirmed_at) values
 ('f7100000-0000-4000-8000-000000000001','offer-staff@example.test',now(),null,null),
 ('f7100000-0000-4000-8000-000000000002',null,null,'46700007102',now()),
 ('f7100000-0000-4000-8000-000000000003',null,null,'46700007103',now()),
 ('f7100000-0000-4000-8000-000000000004','offer-reader@example.test',now(),null,null);
set local role authenticated;
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000001","role":"authenticated"}';
select create_tenant('Synthetic offer recipient','synthetic-offer-recipient',gen_random_uuid()) as tenant \gset
select publish_seller_agreement(:'tenant','f7100000-0000-4000-8000-000000000101',null,'Synthetic agreement 1','Original synthetic terms','sv',true);
reset role;
update public.platform_settings set central_app_tenant_id=:'tenant';
insert into tenant_members(tenant_id,user_id,role) values(:'tenant','f7100000-0000-4000-8000-000000000004','readonly');
set local role authenticated;
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000002","role":"authenticated"}';
select reserve_external_item_photo('f7100000-0000-4000-8000-000000000201',repeat('a',64),100);
insert into storage.objects(bucket_id,name) values('external-item-photos','f7100000-0000-4000-8000-000000000002/f7100000-0000-4000-8000-000000000201.jpg');
select submit_external_item_request('f7100000-0000-4000-8000-000000000301',:'tenant','Jacket','','good','',100000,'SEK',array['f7100000-0000-4000-8000-000000000201']::uuid[],'SE');
select is((select agreement_version_id from external_item_requests where id='f7100000-0000-4000-8000-000000000301'),'f7100000-0000-4000-8000-000000000101'::uuid,'request retains the agreement version for its upload');
select throws_ok(format($$select issue_external_item_offer(%L,'f7100000-0000-4000-8000-000000000401','f7100000-0000-4000-8000-000000000301',null,40000,100000,'f7100000-0000-4000-8000-000000000101')$$,:'tenant'),'42501',null,'phone owner cannot issue a store offer');
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000004","role":"authenticated"}';
select throws_ok(format($$select issue_external_item_offer(%L,'f7100000-0000-4000-8000-000000000401','f7100000-0000-4000-8000-000000000301',null,40000,100000,'f7100000-0000-4000-8000-000000000101')$$,:'tenant'),'42501',null,'readonly staff cannot issue offers');
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_like(format($$select issue_external_item_offer(%L,gen_random_uuid(),'f7100000-0000-4000-8000-000000000301',null,1.5,100000,'f7100000-0000-4000-8000-000000000101')$$,:'tenant'),'%INVALID_INPUT%','fractional ore is rejected');
select is(issue_external_item_offer(:'tenant','f7100000-0000-4000-8000-000000000401','f7100000-0000-4000-8000-000000000301',null,40000,100000,'f7100000-0000-4000-8000-000000000101'),'f7100000-0000-4000-8000-000000000401'::uuid,'staff issue the fixed offer');
select is((select seller_amount_ore::text from external_item_offers limit 1),'40000','seller amount is an exact integer in ore');
select is((select expires_at-created_at from external_item_offers limit 1),interval '48 hours','offer lasts exactly 48 hours');
select lives_ok(format($$select issue_external_item_offer(%L,'f7100000-0000-4000-8000-000000000401','f7100000-0000-4000-8000-000000000301',null,40000,100000,'f7100000-0000-4000-8000-000000000101')$$,:'tenant'),'issue retry returns the original offer');
select throws_like(format($$select issue_external_item_offer(%L,'f7100000-0000-4000-8000-000000000401','f7100000-0000-4000-8000-000000000301',null,50000,100000,'f7100000-0000-4000-8000-000000000101')$$,:'tenant'),'%REQUEST_CONFLICT%','a retry cannot change compensation');
select throws_like(format($$select issue_external_item_offer(%L,gen_random_uuid(),'f7100000-0000-4000-8000-000000000301','f7100000-0000-4000-8000-000000000401',50000,100000,'f7100000-0000-4000-8000-000000000101')$$,:'tenant'),'%OFFER_ACTIVE%','an unanswered live offer cannot be replaced');
select throws_like(format($$select decline_external_item_request(gen_random_uuid(),%L,'f7100000-0000-4000-8000-000000000301','')$$,:'tenant'),'%OFFER_ACTIVE%','staff cannot withdraw a live offer by declining the request');
select publish_seller_agreement(:'tenant','f7100000-0000-4000-8000-000000000102','f7100000-0000-4000-8000-000000000101','Synthetic agreement 2','Later synthetic terms','sv',true);
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000003","role":"authenticated"}';
select is((select count(*) from external_item_offers),0::bigint,'another phone user cannot read the offer');
select throws_like($$select read_external_item_offer('f7100000-0000-4000-8000-000000000401')$$,'%OFFER_NOT_FOUND%','detail read protects another owner agreement');
select throws_like($$select my_external_item_offers(array['f7100000-0000-4000-8000-000000000301']::uuid[])$$,'%OFFER_NOT_FOUND%','list refuses foreign request IDs');
select throws_like($$select respond_external_item_offer(gen_random_uuid(),'f7100000-0000-4000-8000-000000000401',true,'f7100000-0000-4000-8000-000000000101')$$,'%OFFER_NOT_FOUND%','another identity cannot accept it');
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000002","role":"authenticated"}';
select is((select agreement_version_id from external_item_offers limit 1),'f7100000-0000-4000-8000-000000000101'::uuid,'later agreements do not rewrite an earlier offer');
select is(read_external_item_offer('f7100000-0000-4000-8000-000000000401')#>>'{agreement,body}','Original synthetic terms','owner reads the frozen agreement without tenant membership');
select is(my_external_item_offers(array['f7100000-0000-4000-8000-000000000301']::uuid[])#>>'{offers,0,status}','offered','mobile reads a real offer status separately from the legacy list');
select is(my_external_item_offers(array['f7100000-0000-4000-8000-000000000301']::uuid[])#>'{offers,0,agreement}',null::jsonb,'paged summaries omit large legal texts');
select throws_like($$select respond_external_item_offer(gen_random_uuid(),'f7100000-0000-4000-8000-000000000401',true,'f7100000-0000-4000-8000-000000000102')$$,'%AGREEMENT_CHANGED%','acceptance must identify the displayed frozen agreement');
select is(respond_external_item_offer('f7100000-0000-4000-8000-000000000501','f7100000-0000-4000-8000-000000000401',true,'f7100000-0000-4000-8000-000000000101'),'f7100000-0000-4000-8000-000000000501'::uuid,'seller accepts the exact offer and agreement');
select lives_ok($$select respond_external_item_offer('f7100000-0000-4000-8000-000000000501','f7100000-0000-4000-8000-000000000401',true,'f7100000-0000-4000-8000-000000000101')$$,'acceptance retries safely');
select throws_like($$select respond_external_item_offer(gen_random_uuid(),'f7100000-0000-4000-8000-000000000401',false,null)$$,'%REQUEST_CHANGED%','a completed response cannot be overwritten');
select is(my_external_item_requests()->>'activeCount','1','accepted but not handed-in item still consumes one slot');
select is(read_external_item_offer('f7100000-0000-4000-8000-000000000401')->>'canAccept','false','completed response cannot render an enabled accept action');
select is(my_external_item_requests()#>>'{requests,0,status}','waiting','existing mobile list contract remains compatible');
select submit_external_item_request('f7100000-0000-4000-8000-000000000302',:'tenant','Lamp','','good','',null,'SEK',array['f7100000-0000-4000-8000-000000000201']::uuid[],'SE');
select is((select agreement_version_id from external_item_requests where id='f7100000-0000-4000-8000-000000000302'),'f7100000-0000-4000-8000-000000000102'::uuid,'later uploads bind the new agreement');
select throws_ok($$insert into external_item_offer_responses(id,offer_id,owner_id,accepted,agreement_version_id) values(gen_random_uuid(),'f7100000-0000-4000-8000-000000000401','f7100000-0000-4000-8000-000000000002',true,'f7100000-0000-4000-8000-000000000101')$$,'42501',null,'direct response writes are denied');
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_like(format($$select decline_external_item_request(gen_random_uuid(),%L,'f7100000-0000-4000-8000-000000000301','')$$,:'tenant'),'%OFFER_ACCEPTED%','accepted offers cannot be declined by staff');
select issue_external_item_offer(:'tenant','f7100000-0000-4000-8000-000000000402','f7100000-0000-4000-8000-000000000302',null,20000,50000,'f7100000-0000-4000-8000-000000000102');
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000002","role":"authenticated"}';
select respond_external_item_offer('f7100000-0000-4000-8000-000000000502','f7100000-0000-4000-8000-000000000402',false,null);
select is(my_external_item_requests()->>'activeCount','1','seller refusal releases exactly one slot');
select lives_ok($$select respond_external_item_offer('f7100000-0000-4000-8000-000000000502','f7100000-0000-4000-8000-000000000402',false,null)$$,'refusal retries safely');
select submit_external_item_request('f7100000-0000-4000-8000-000000000303',:'tenant','Expired test','','good','',null,'SEK',array['f7100000-0000-4000-8000-000000000201']::uuid[],'SE');
reset role;
insert into external_item_offers(id,tenant_id,request_id,owner_id,seller_amount_ore,expected_sale_price_ore,agreement_version_id,created_by,created_at,expires_at)
 values('f7100000-0000-4000-8000-000000000403',:'tenant','f7100000-0000-4000-8000-000000000303','f7100000-0000-4000-8000-000000000002',30000,90000,'f7100000-0000-4000-8000-000000000102','f7100000-0000-4000-8000-000000000001',statement_timestamp()-interval '49 hours',statement_timestamp()-interval '1 hour');
set local role authenticated;
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_like($$select respond_external_item_offer(gen_random_uuid(),'f7100000-0000-4000-8000-000000000403',true,'f7100000-0000-4000-8000-000000000102')$$,'%OFFER_EXPIRED%','server rejects acceptance after expiry');
select is(read_external_item_offer('f7100000-0000-4000-8000-000000000403')->>'status','expired','expired deadline is explicit in the read model');
select lives_ok($$select respond_external_item_offer(gen_random_uuid(),'f7100000-0000-4000-8000-000000000403',false,null)$$,'seller can close an expired offer without accepting it');
select is(my_external_item_requests()->>'activeCount','1','closing an expired offer releases its slot');
select throws_ok(format($$select external_item_offer_queue(%L,0)$$,:'tenant'),'42501',null,'phone owners cannot read the staff queue');
set local request.jwt.claims='{"sub":"f7100000-0000-4000-8000-000000000004","role":"authenticated"}';
select is(external_item_offer_queue(:'tenant',0)->>'total','3','readonly staff can inspect their own queue');
select is(jsonb_array_length(external_item_offer_queue(:'tenant',25)->'rows'),0,'queue offset is applied before returning rows');
select throws_like(format($$select external_item_offer_queue(%L,-1)$$,:'tenant'),'%INVALID_INPUT%','queue rejects invalid paging');
select throws_ok($$select external_item_offer_queue('f7100000-0000-4000-8000-000000000999',0)$$,'42501',null,'queue cannot cross tenant boundaries');
select ok(not exists(select 1 from jsonb_array_elements(external_item_offer_queue(:'tenant',0)->'rows') r where r#>'{offer,agreement}' is not null),'queue summaries omit agreement bodies');
reset role;
select is((select count(*) from sellers where tenant_id=:'tenant'),0::bigint,'offer responses alone create no seller');
select is((select count(*) from tenant_members where user_id='f7100000-0000-4000-8000-000000000002'),0::bigint,'offer responses grant no membership');
select throws_like($$update external_item_offers set seller_amount_ore=1$$,'%IMMUTABLE%','offers are immutable even under privileged SQL');
select throws_like($$delete from external_item_offer_responses$$,'%IMMUTABLE%','responses are immutable even under privileged SQL');
select * from finish();
rollback;
